{"path": "/tmp/sv-b05d3b5fd22e499c975384a74fab5392/Components/Catalog/CatalogPagination.razor", "file_text": "<div class="catalog-pagination">
    <button class="btn btn-page" disabled="@(CurrentPage <= 1)" @onclick="GoToPrevious">
        Previous
    </button>

    @for (int i = 1; i <= TotalPages; i++)
    {
        var pageNumber = i;
        <button class="btn btn-page @(pageNumber == CurrentPage ? "active" : "")"
                @onclick="@(() => GoToPage(pageNumber))">
            @pageNumber
